import { mapRefs } from "../convert/schema.js";
import { deepClone, isPlainObject } from "../util/json.js";

/**
 * Swagger 2.0 -> OpenAPI 3.1 converter.
 *
 * Many real-world services (Rainyun, older Go/Java stacks, docs generated by
 * swaggo) still publish Swagger 2.0 documents. They look similar but differ in
 * ways that silently break tool generation:
 *   - request bodies are `in: body` / `in: formData` parameters, not
 *     `requestBody`;
 *   - parameter schemas are inlined (`type`, `items`, `enum` on the parameter);
 *   - shared schemas live in `definitions` (`#/definitions/X` refs);
 *   - auth lives in `securityDefinitions`, with `type: basic` / `oauth2` flows;
 *   - the base URL is split into `schemes` + `host` + `basePath`.
 *
 * The output is a plain OpenAPI 3.1 object that the rest of the pipeline
 * understands. Only what the bridge needs is converted faithfully; response
 * schemas are kept on a best-effort basis.
 */

export class Swagger2Error extends Error {}

/** Keys on a non-body parameter that are not part of its JSON Schema. */
const PARAM_META_KEYS = new Set([
  "name",
  "in",
  "required",
  "description",
  "collectionFormat",
  "allowEmptyValue",
  "schema",
  "x-example",
]);

/** HTTP methods that can appear in a path item. */
const METHODS = ["get", "put", "post", "delete", "options", "head", "patch", "trace"] as const;

function asArray(value: unknown): unknown[] {
  return Array.isArray(value) ? value : [];
}

/** Extract a JSON Schema from a Swagger 2 non-body parameter. */
function parameterSchema(param: Record<string, unknown>): Record<string, unknown> {
  if (isPlainObject(param.schema)) {
    const schema = deepClone(param.schema);
    return fixFileType(schema);
  }
  const schema: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(param)) {
    if (PARAM_META_KEYS.has(key) || key.startsWith("x-")) continue;
    schema[key] = deepClone(value);
  }
  if (Object.keys(schema).length === 0) schema.type = "string";
  return fixFileType(schema);
}

/** Swagger's `type: file` becomes a binary string in OpenAPI 3. */
function fixFileType(schema: Record<string, unknown>): Record<string, unknown> {
  if (schema.type === "file") {
    schema.type = "string";
    schema.format = "binary";
  }
  if (isPlainObject(schema.items)) fixFileType(schema.items);
  return schema;
}

/** `collectionFormat` -> `style` / `explode`. */
function collectionStyle(
  location: string,
  collectionFormat: unknown,
): { style?: string; explode?: boolean } {
  switch (collectionFormat) {
    case "multi":
      return location === "query" || location === "formData" ? { style: "form", explode: true } : {};
    case "ssv":
      return { style: "spaceDelimited", explode: false };
    case "pipes":
      return { style: "pipeDelimited", explode: false };
    case "csv":
      return { style: "form", explode: false };
    default:
      return {};
  }
}

function convertParameter(raw: unknown): Record<string, unknown> | null {
  if (!isPlainObject(raw)) return null;
  const location = typeof raw.in === "string" ? raw.in : "";
  if (!["path", "query", "header", "cookie"].includes(location)) return null;
  const name = typeof raw.name === "string" ? raw.name : "";
  if (!name) return null;

  const parameter: Record<string, unknown> = {
    name,
    in: location,
    required: location === "path" ? true : raw.required === true,
    schema: parameterSchema(raw),
  };
  if (typeof raw.description === "string" && raw.description) parameter.description = raw.description;
  if (raw.allowEmptyValue === true) parameter.allowEmptyValue = true;
  Object.assign(parameter, collectionStyle(location, raw.collectionFormat));
  return parameter;
}

/** Resolve `$ref: "#/parameters/X"` entries, which Swagger 2 allows in parameter arrays. */
function expandParameters(params: unknown[], doc: Record<string, unknown>): unknown[] {
  const shared = isPlainObject(doc.parameters) ? doc.parameters : {};
  return params.map((param) => {
    if (!isPlainObject(param) || typeof param.$ref !== "string") return param;
    const match = /^#\/parameters\/(.+)$/.exec(param.$ref);
    if (!match) return param;
    const target = shared[match[1]];
    return isPlainObject(target) ? target : param;
  });
}

function mediaTypeFor(value: unknown, fallback: string): string {
  const list = asArray(value).filter((item): item is string => typeof item === "string" && item.length > 0);
  return list[0] ?? fallback;
}

function convertRequestBody(
  body: Record<string, unknown> | undefined,
  form: Record<string, unknown>[],
  consumes: unknown,
): Record<string, unknown> | undefined {
  if (body) {
    const schema = isPlainObject(body.schema) ? fixFileType(deepClone(body.schema)) : { type: "object" };
    const contentType = mediaTypeFor(consumes, "application/json");
    const requestBody: Record<string, unknown> = {
      required: body.required === true,
      content: { [contentType]: { schema } },
    };
    if (typeof body.description === "string" && body.description) requestBody.description = body.description;
    return requestBody;
  }

  if (form.length > 0) {
    const properties: Record<string, unknown> = {};
    const required: string[] = [];
    let hasFile = false;
    for (const field of form) {
      const name = typeof field.name === "string" ? field.name : "";
      if (!name) continue;
      properties[name] = parameterSchema(field);
      if (field.required === true) required.push(name);
      if (field.type === "file") hasFile = true;
    }
    const schema: Record<string, unknown> = { type: "object", properties };
    if (required.length > 0) schema.required = required;
    const declared = asArray(consumes).filter(
      (item): item is string =>
        typeof item === "string" && (item === "multipart/form-data" || item === "application/x-www-form-urlencoded"),
    );
    const contentType = declared[0] ?? (hasFile ? "multipart/form-data" : "application/x-www-form-urlencoded");
    return {
      required: required.length > 0,
      content: { [contentType]: { schema } },
    };
  }

  return undefined;
}

function convertResponses(raw: unknown, produces: unknown): Record<string, unknown> {
  const out: Record<string, unknown> = {};
  if (!isPlainObject(raw)) return { default: { description: "" } };
  for (const [status, response] of Object.entries(raw)) {
    if (!isPlainObject(response)) continue;
    const next: Record<string, unknown> = {
      description: typeof response.description === "string" ? response.description : "",
    };
    if (isPlainObject(response.schema)) {
      const contentType = mediaTypeFor(produces, "application/json");
      next.content = { [contentType]: { schema: deepClone(response.schema) } };
    }
    if (isPlainObject(response.headers)) {
      const headers: Record<string, unknown> = {};
      for (const [name, header] of Object.entries(response.headers)) {
        if (!isPlainObject(header)) continue;
        const schema: Record<string, unknown> = {};
        for (const [key, value] of Object.entries(header)) {
          if (key === "description") continue;
          schema[key] = deepClone(value);
        }
        const headerOut: Record<string, unknown> = { schema };
        if (typeof header.description === "string" && header.description) headerOut.description = header.description;
        headers[name] = headerOut;
      }
      if (Object.keys(headers).length > 0) next.headers = headers;
    }
    if (isPlainObject(response.examples) && isPlainObject(next.content)) {
      for (const [contentType, media] of Object.entries(next.content)) {
        const example = response.examples[contentType];
        if (example !== undefined && isPlainObject(media)) media.example = deepClone(example);
      }
    }
    out[status] = next;
  }
  if (Object.keys(out).length === 0) out.default = { description: "" };
  return out;
}

function convertSecuritySchemes(raw: unknown): Record<string, unknown> {
  const out: Record<string, unknown> = {};
  if (!isPlainObject(raw)) return out;
  for (const [name, scheme] of Object.entries(raw)) {
    if (!isPlainObject(scheme)) continue;
    const description = typeof scheme.description === "string" ? scheme.description : undefined;
    if (scheme.type === "apiKey") {
      const converted: Record<string, unknown> = {
        type: "apiKey",
        in: scheme.in === "query" ? "query" : scheme.in === "cookie" ? "cookie" : "header",
        name: typeof scheme.name === "string" ? scheme.name : name,
      };
      if (description) converted.description = description;
      out[name] = converted;
      continue;
    }
    if (scheme.type === "basic") {
      const converted: Record<string, unknown> = { type: "http", scheme: "basic" };
      if (description) converted.description = description;
      out[name] = converted;
      continue;
    }
    if (scheme.type === "oauth2") {
      const flow = String(scheme.flow ?? "implicit");
      const scopes = isPlainObject(scheme.scopes) ? scheme.scopes : {};
      const flowName =
        flow === "application"
          ? "clientCredentials"
          : flow === "accessCode"
            ? "authorizationCode"
            : flow === "password"
              ? "password"
              : "implicit";
      const details: Record<string, unknown> = { scopes };
      if (flowName === "implicit" || flowName === "authorizationCode") details.authorizationUrl = scheme.authorizationUrl ?? "";
      if (flowName === "password" || flowName === "clientCredentials" || flowName === "authorizationCode") {
        details.tokenUrl = scheme.tokenUrl ?? "";
      }
      const converted: Record<string, unknown> = { type: "oauth2", flows: { [flowName]: details } };
      if (description) converted.description = description;
      out[name] = converted;
      continue;
    }
    out[name] = deepClone(scheme);
  }
  return out;
}

function buildServers(doc: Record<string, unknown>): Array<{ url: string }> | undefined {
  const host = typeof doc.host === "string" ? doc.host.trim() : "";
  const basePath = typeof doc.basePath === "string" ? doc.basePath.trim() : "";
  if (!host) return undefined;
  const schemes = asArray(doc.schemes).filter((item): item is string => typeof item === "string" && item.length > 0);
  const scheme = schemes.includes("https") ? "https" : (schemes[0] ?? "https");
  const path = basePath && basePath !== "/" ? `/${basePath.replace(/^\/+|\/+$/g, "")}` : "";
  return [{ url: `${scheme}://${host}${path}` }];
}

function convertPathItem(
  item: Record<string, unknown>,
  consumes: unknown,
  produces: unknown,
  doc: Record<string, unknown>,
): Record<string, unknown> {
  const out: Record<string, unknown> = {};

  // Path-level parameters are shared by every operation.
  const pathParams = expandParameters(asArray(item.parameters), doc);
  if (pathParams.length > 0) {
    out.parameters = pathParams.map(convertParameter).filter((value) => value !== null);
  }
  for (const [key, value] of Object.entries(item)) {
    if (key === "parameters" || METHODS.includes(key as (typeof METHODS)[number])) continue;
    out[key] = deepClone(value);
  }

  for (const method of METHODS) {
    const operation = item[method];
    if (!isPlainObject(operation)) continue;

    const opConsumes = Array.isArray(operation.consumes) ? operation.consumes : consumes;
    const opProduces = Array.isArray(operation.produces) ? operation.produces : produces;
    const ownParams = expandParameters(asArray(operation.parameters), doc);
    const params = [...pathParams, ...ownParams];
    const bodyParam = params.find((param) => isPlainObject(param) && param.in === "body") as
      | Record<string, unknown>
      | undefined;
    const formParams = params.filter(
      (param): param is Record<string, unknown> => isPlainObject(param) && param.in === "formData",
    );

    const convertedParams = ownParams
      .map(convertParameter)
      .filter((param): param is Record<string, unknown> => param !== null);

    const next: Record<string, unknown> = {};
    for (const [key, value] of Object.entries(operation)) {
      if (["parameters", "consumes", "produces", "responses"].includes(key)) continue;
      if (key === "schemes") continue;
      next[key] = deepClone(value);
    }
    if (convertedParams.length > 0) next.parameters = convertedParams;
    next.responses = convertResponses(operation.responses, opProduces);

    const requestBody = convertRequestBody(bodyParam, formParams, opConsumes);
    if (requestBody) next.requestBody = requestBody;

    out[method] = next;
  }

  return out;
}

export function isSwagger2Document(doc: unknown): doc is Record<string, unknown> {
  return isPlainObject(doc) && typeof doc.swagger === "string" && doc.swagger.startsWith("2");
}

/**
 * Convert a Swagger 2.0 document into an OpenAPI 3.1 document.
 * Throws `Swagger2Error` when the input is not a usable Swagger 2 document.
 */
export function convertSwagger2ToOpenApi(input: unknown): Record<string, unknown> {
  if (!isPlainObject(input)) throw new Swagger2Error("Swagger 2.0 document must be an object");
  if (!isSwagger2Document(input)) throw new Swagger2Error("Not a Swagger 2.0 document");
  if (!isPlainObject(input.paths)) throw new Swagger2Error("Swagger 2.0 document has no \"paths\" object");

  const doc = input;
  const consumes = doc.consumes;
  const produces = doc.produces;

  // Start from the untouched keys that are valid in both dialects.
  const output: Record<string, unknown> = {
    openapi: "3.1.0",
    info: isPlainObject(doc.info) ? deepClone(doc.info) : { title: "Converted API", version: "1.0.0" },
    paths: {},
  };
  for (const key of ["tags", "externalDocs", "x-bridge"]) {
    if (doc[key] !== undefined) output[key] = deepClone(doc[key]);
  }

  const servers = buildServers(doc);
  if (servers) output.servers = servers;

  const paths: Record<string, unknown> = {};
  for (const [pathname, item] of Object.entries(input.paths as Record<string, unknown>)) {
    if (!isPlainObject(item)) continue;
    paths[pathname] = convertPathItem(item, consumes, produces, doc);
  }
  output.paths = paths;

  const components: Record<string, unknown> = {};
  if (isPlainObject(doc.definitions)) {
    const definitions = deepClone(doc.definitions);
    for (const [name, definition] of Object.entries(definitions)) {
      if (isPlainObject(definition)) fixFileType(definition);
    }
    components.schemas = definitions;
  }
  if (isPlainObject(doc.securityDefinitions)) {
    components.securitySchemes = convertSecuritySchemes(doc.securityDefinitions);
  }
  if (isPlainObject(doc.parameters)) {
    const parameters: Record<string, unknown> = {};
    for (const [name, parameter] of Object.entries(doc.parameters)) {
      const converted = convertParameter(parameter);
      if (converted) parameters[name] = converted;
    }
    components.parameters = parameters;
  }
  if (Object.keys(components).length > 0) output.components = components;

  if (Array.isArray(doc.security)) output.security = deepClone(doc.security);

  // Rewrite `#/definitions/X` refs (and parameter refs) to their 3.x homes.
  return mapRefs(output, (ref) => {
    if (ref.startsWith("#/definitions/")) return `#/components/schemas/${ref.slice("#/definitions/".length)}`;
    if (ref.startsWith("#/parameters/")) return `#/components/parameters/${ref.slice("#/parameters/".length)}`;
    if (ref.startsWith("#/responses/")) return `#/components/responses/${ref.slice("#/responses/".length)}`;
    return ref;
  });
}
